const evalTFBank=[{"q":"El objeto de deseo tiene que ser concreto: se tiene que poder ver el momento en que el personaje lo consigue.","a":true},{"q":"«Ser feliz» es un buen objetivo para una historia porque le importa a todo el mundo.","a":false},{"q":"Para Propp (1928), el obstáculo es una función o rol (el agresor), no necesariamente una persona.","a":true},{"q":"Propp encontró 31 funciones en los cuentos maravillosos rusos que analizó.","a":true},{"q":"Truby (2007) sostiene que el personaje quiere y necesita siempre exactamente lo mismo.","a":false},{"q":"La apuesta es lo que se pierde si el deseo no se cumple, y sin ella no hay atención.","a":true},{"q":"«La vida» y «el sistema» sirven como obstáculo porque son fuerzas muy poderosas.","a":false},{"q":"Egri (1946) llama premisa a la frase que dice qué demuestra la historia.","a":true},{"q":"La unidad de la acción de Aristóteles pide que todos los sucesos estén atados a una sola acción.","a":true},{"q":"En Propp, un mismo personaje nunca puede cubrir dos esferas de acción.","a":false},{"q":"El deseo consciente y el inconsciente de McKee (1997) pueden chocar entre sí.","a":true},{"q":"Un obstáculo puede ser la propia contradicción del que quiere.","a":true},{"q":"La necesidad moral de Truby (2007) tiene que ver con dejar de hacer daño a otros, no solo a uno mismo.","a":true},{"q":"Si el personaje consigue lo que pedía y no cambia nada por dentro, hay una historia completa.","a":false},{"q":"El límite de la «Poética» de Aristóteles es que describe la tragedia griega, no toda narración.","a":true}];
const evalMCBank=[{"q":"¿Qué hace que un objetivo sirva para una historia?","o":["a) Que sea noble","b) Que se pueda ver el momento en que se consigue","c) Que emocione","d) Que sea difícil"],"a":1},{"q":"Según McKee (1997), ¿qué es el objeto de deseo?","o":["a) El final de la historia","b) Lo que el personaje persigue y organiza su acción","c) El defecto del héroe","d) El paisaje"],"a":1},{"q":"¿Por qué «la vida» no sirve como obstáculo?","o":["a) Porque un obstáculo abstracto no se puede ver ni enfrentar, así que no hay escena","b) Porque suena pesimista","c) Porque es política","d) Porque es larga de explicar"],"a":0},{"q":"Propp (1928) mostró que el obstáculo es sobre todo...","o":["a) Una función o rol (el agresor), no una persona","b) Una casualidad","c) Un sentimiento","d) Un defecto del héroe"],"a":0},{"q":"¿Cuántas funciones encontró Propp en los cuentos que analizó?","o":["a) 7","b) 12","c) 100","d) 31"],"a":3},{"q":"La distinción de Truby (2007) entre querer y necesitar dice que...","o":["a) Querer y necesitar son lo mismo","b) Solo importa lo que necesita","c) El deseo siempre se cumple","d) El personaje quiere una cosa y necesita otra, y ahí nace el cambio"],"a":3},{"q":"¿Qué es la apuesta de una historia?","o":["a) Lo que se pierde si el deseo no se cumple, y sin ella no hay atención","b) El número de escenas","c) El tono","d) El narrador"],"a":0},{"q":"Egri (1946) sostiene que sin cierto ingrediente no arranca una historia. ¿Cuál?","o":["a) Un personaje que quiera con voluntad","b) Un final feliz","c) Una descripción del paisaje","d) Un narrador omnisciente"],"a":0},{"q":"¿Qué es una esfera de acción en Propp?","o":["a) El lugar del cuento","b) Un rol (el donante, el auxiliar) que un personaje puede cubrir o repartir","c) El número de páginas","d) La moraleja"],"a":1},{"q":"La unidad de la acción de Aristóteles pide que...","o":["a) Haya un solo personaje","b) La historia dure poco","c) No haya diálogos","d) Todos los sucesos estén atados a una sola acción"],"a":3},{"q":"¿Qué se puede hacer con una función que no se puede hacer con un villano?","o":["a) Combatirla, y solo eso","b) Ignorarla","c) Rodearla, convencer a quien la cumple o buscar a otro que cumpla la contraria","d) Nada distinto"],"a":2},{"q":"En «Anillos para una dama» (1973) de Gala, ¿qué se le interpone a Jimena?","o":["a) Un dragón","b) Su propio mito: España la necesita viuda del Cid, no mujer","c) Una ley del rey","d) La falta de dinero"],"a":1},{"q":"¿Cuál es la diferencia entre lo que un personaje quiere y lo que necesita?","o":["a) Ninguna, son sinónimos","b) El querer es del autor y el necesitar del lector","c) Lo quiere lo dice él; lo necesita lo sabe antes el público, y la distancia es el tamaño de la historia","d) El necesitar siempre es material"],"a":2},{"q":"¿Qué diferencia a Propp (1928) de Campbell (1949), según la casa?","o":["a) Propp era más famoso","b) Campbell midió más cuentos","c) Propp contó lo que había en un género y lo dijo; Campbell afirmó que su patrón valía para todos, que no se puede demostrar","d) No hay diferencia"],"a":2},{"q":"¿Qué firman las dos partes del careo de esta etapa?","o":["a) Que el conflicto es obligatorio","b) Que Lévi-Strauss tenía toda la razón","c) Que en el centro de una historia hay un deseo y una oposición, y que el obstáculo se entiende mejor como función que como persona","d) Que las estructuras son leyes universales"],"a":2}];
const evalCPBank=[{"q":"Lo que el personaje persigue es el objeto de ___.","a":"deseo"},{"q":"Un objetivo sirve si se puede ___ el momento en que se consigue.","a":"ver"},{"q":"Lo que se pierde si el deseo no se cumple es la ___.","a":"apuesta"},{"q":"Para Propp el obstáculo es una ___, no una persona.","a":"función"},{"q":"Truby distingue el querer de lo que se ___.","a":"necesita"},{"q":"El obstáculo tiene que tener ___: una persona, una regla o un plazo.","a":"cara"},{"q":"Egri llama ___ a la frase que dice qué demuestra la historia.","a":"premisa"},{"q":"Aristóteles pide una sola ___ en la «Poética».","a":"acción"},{"q":"Propp encontró ___ funciones en los cuentos rusos.","a":"31"},{"q":"Los siete roles de Propp se llaman esferas de ___.","a":"acción"},{"q":"El rol que se opone al héroe en Propp es el ___.","a":"agresor"},{"q":"El rol que da algo que ayuda al héroe es el ___.","a":"donante"},{"q":"Cuando el que se opone al deseo es el mismo que lo tiene, el obstáculo es ___.","a":"interno"},{"q":"La libreta donde esta casa guarda sus historias es el Cuaderno de ___.","a":"hilos"},{"q":"El apellido del folclorista de las 31 funciones es ___.","a":"Propp"}];
const evalPRBank=[{"term":"Objeto de deseo","def":"Lo que el personaje persigue (McKee, 1997)"},{"term":"La apuesta","def":"Lo que se pierde si el deseo no se cumple"},{"term":"El obstáculo","def":"La fuerza con cara que se opone al deseo"},{"term":"Querer (want)","def":"Lo que el personaje pide en voz alta"},{"term":"Necesitar (need)","def":"Lo que de verdad le hace falta (Truby, 2007)"},{"term":"Función","def":"El obstáculo como rol y no como persona (Propp, 1928)"},{"term":"Esfera de acción","def":"Uno de los siete roles de Propp"},{"term":"El agresor","def":"El rol que se opone al héroe"},{"term":"El donante","def":"El rol que da algo que ayuda"},{"term":"La premisa","def":"Qué demuestra la historia (Egri, 1946)"},{"term":"Unidad de la acción","def":"Todo atado a una sola acción (Aristóteles)"},{"term":"Objetivo concreto","def":"Se puede ver el momento en que se consigue"},{"term":"«La vida» como obstáculo","def":"Un obstáculo abstracto que no genera escena"},{"term":"El obstáculo interno","def":"La propia contradicción del que quiere"},{"term":"La necesidad moral","def":"Dejar de hacer daño a otros (Truby, 2007)"}];
function genEval(){sfx('click');_evalFormaSelector();const _selF=document.getElementById('evalFormaSel');if(_selF&&parseInt(_selF.value,10))evalFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_selF.value,10)));const cf=evalFormNum;const rng=_evalRng(cf);window._currentEvalForm=cf;evalFormNum=(evalFormNum%EVAL_FORMAS)+1;_evalFormaSelector();saveProgress();document.getElementById('eval-screen-title').textContent=`🎓 Evaluación Final · Forma ${cf} · El deseo y el obstáculo · Ruta del Hilo que Tira`;evalAnsVisible=false;const out=document.getElementById('evalOut');out.innerHTML='';const bar=document.createElement('div');bar.className='eval-score-bar';bar.innerHTML=`<div><div class="esb-title">📊 Distribución de puntaje · 100 puntos</div><div class="esb-dist">Cada sección vale 25 puntos (5 preguntas × 5 pts)</div></div><div style="display:flex;gap:0.4rem;flex-wrap:wrap;"><span class="eval-score-pill esp-cp">Completar 25 pts</span><span class="eval-score-pill esp-tf">V/F 25 pts</span><span class="eval-score-pill esp-mc">Selección 25 pts</span><span class="eval-score-pill esp-pr">Pareados 25 pts</span></div>`;out.appendChild(bar);const cpItems=_pickF(evalCPBank,5,rng);const s1=document.createElement('div');s1.innerHTML='<div class="eval-section-title">I. Completar el espacio <span class="eval-pts">25 pts · 5 pts c/u</span></div>';cpItems.forEach((item,i)=>{const d=document.createElement('div');d.className='eval-item eval-auto-item';d.dataset.evalType='cp';d.dataset.evalIndex=i;const qHtml=item.q.replace('___',`<input class="eval-cp-input" type="text" data-cp="${i}" autocomplete="off">`);d.innerHTML=`<div class="eval-q"><span class="eval-num">${i+1}</span><span class="eval-q-text">${qHtml}</span></div><div class="eval-answer">${item.a}</div><div class="eval-item-feedback" id="evalFbCp${i}" aria-live="polite"></div>`;s1.appendChild(d);});out.appendChild(s1);const tfItems=_pickF(evalTFBank,5,rng);const s2=document.createElement('div');s2.innerHTML='<div class="eval-section-title">II. Verdadero o Falso <span class="eval-pts">25 pts · 5 pts c/u</span></div>';tfItems.forEach((item,i)=>{const d=document.createElement('div');d.className='eval-item eval-auto-item';d.dataset.evalType='tf';d.dataset.evalIndex=i;d.innerHTML=`<div class="eval-q"><span class="eval-num">${i+6}</span><span class="eval-q-text">${item.q}</span></div><div class="eval-tf-opts"><label class="eval-tf-opt"><input type="radio" name="tf${i}" value="true"> Verdadero</label><label class="eval-tf-opt"><input type="radio" name="tf${i}" value="false"> Falso</label></div><div class="eval-answer">${item.a?'Verdadero':'Falso'}</div><div class="eval-item-feedback" id="evalFbTf${i}" aria-live="polite"></div>`;s2.appendChild(d);});out.appendChild(s2);const mcItems=_pickF(evalMCBank,5,rng);const s3=document.createElement('div');s3.innerHTML='<div class="eval-section-title">III. Selección Múltiple <span class="eval-pts">25 pts · 5 pts c/u</span></div>';mcItems.forEach((item,i)=>{const d=document.createElement('div');d.className='eval-item eval-auto-item';d.dataset.evalType='mc';d.dataset.evalIndex=i;const optsHtml=item.o.map((op,oi)=>`<label class="eval-mc-opt"><input type="radio" name="mc${i}" value="${oi}"> ${op}</label>`).join('');d.innerHTML=`<div class="eval-q"><span class="eval-num">${i+11}</span><span class="eval-q-text">${item.q}</span></div><div class="eval-mc-opts">${optsHtml}</div><div class="eval-answer">${item.o[item.a]}</div><div class="eval-item-feedback" id="evalFbMc${i}" aria-live="polite"></div>`;s3.appendChild(d);});out.appendChild(s3);const prItems=_pickF(evalPRBank,5,rng);let shuffledDefs=_shuffleF(prItems,rng);let _prTries=0;while(shuffledDefs.some((df,ix)=>df.def===prItems[ix].def)&&_prTries<20){shuffledDefs=_shuffleF(shuffledDefs,rng);_prTries++;}const letters=['A','B','C','D','E'];const s4=document.createElement('div');s4.innerHTML='<div class="eval-section-title">IV. Términos Pareados <span class="eval-pts">25 pts · 5 pts c/u</span></div>';const matchCard=document.createElement('div');matchCard.className='eval-item';let colLeft='<div class="eval-match-col"><h4>📌 Términos</h4>';prItems.forEach((item,i)=>{colLeft+=`<div class="eval-match-item"><span class="eval-match-letter">${i+16}.</span> <select class="eval-match-select" data-pr="${i}" aria-label="Respuesta pareada ${i+16}"><option value="">?</option>${letters.map(l=>`<option value="${l}">${l}</option>`).join('')}</select> ${item.term}</div>`;});colLeft+='</div>';let colRight='<div class="eval-match-col"><h4>🔑 Definiciones</h4>';shuffledDefs.forEach((item,i)=>{colRight+=`<div class="eval-match-item"><span class="eval-match-letter">${letters[i]}.</span> ${item.def}</div>`;});colRight+='</div>';const ansKey=prItems.map((item,i)=>{const letter=letters[shuffledDefs.findIndex(d=>d.def===item.def)];return`${i+16}→${letter}`;}).join(' · ');matchCard.innerHTML=`<div class="eval-match-grid">${colLeft}${colRight}</div><div class="eval-answer" style="display:none;">${ansKey}</div><div class="eval-item-feedback" id="evalFbPr" aria-live="polite"></div>`;s4.appendChild(matchCard);out.appendChild(s4);window._evalPrintData={tf:tfItems,mc:mcItems,cp:cpItems,pr:{terms:prItems,shuffledDefs,letters}};const autoPanel=document.createElement('div');autoPanel.id='evalAutoResult';autoPanel.className='eval-auto-result';autoPanel.innerHTML='<strong>🧮 Evaluación interactiva:</strong> responde en pantalla y presiona <em>Calificar prueba</em>. La impresión conserva el formato original sin respuestas digitadas.';out.appendChild(autoPanel);fin('s-evaluacion');}
function toggleEvalAns(){evalAnsVisible=!evalAnsVisible;document.querySelectorAll('#evalOut .eval-answer').forEach(el=>el.style.display=evalAnsVisible?'block':'none');sfx('click');}
function normalizeEvalAnswer(v){return(v||'').toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/\s+/g,' ').replace(/[()]/g,'').trim();}
function isCpCorrect(student,expected){const s=normalizeEvalAnswer(student);const e=normalizeEvalAnswer(expected);if(!s)return false;const variants=new Set([e]);if(e.includes(' '))e.split(' ').forEach(x=>x&&variants.add(x));return variants.has(s)||e.replace(/[^a-z0-9]/g,'')===s.replace(/[^a-z0-9]/g,'');}
function setEvalFeedback(id,ok,msg){const el=document.getElementById(id);if(!el)return;el.textContent=msg;el.className='eval-item-feedback '+(ok?'eval-ok':'eval-no');}
function gradeEval(){if(!window._evalPrintData){showToast('⚠️ Genera una evaluación primero');return;}sfx('click');const d=window._evalPrintData;let total=0;const detail={cp:0,tf:0,mc:0,pr:0};d.cp.forEach((it,i)=>{const input=document.querySelector(`[data-cp="${i}"]`);const ok=isCpCorrect(input?input.value:'',it.a);if(input){input.classList.toggle('eval-input-ok',ok);input.classList.toggle('eval-input-no',!ok);}if(ok){detail.cp++;total+=5;}setEvalFeedback('evalFbCp'+i,ok,ok?'Correcto. +5 pts':'Revisar. Respuesta esperada: '+it.a);});d.tf.forEach((it,i)=>{const selected=document.querySelector(`input[name="tf${i}"]:checked`);const ok=!!selected&&(selected.value==='true')===it.a;if(ok){detail.tf++;total+=5;}setEvalFeedback('evalFbTf'+i,ok,ok?'Correcto. +5 pts':'Revisar. Respuesta esperada: '+(it.a?'Verdadero':'Falso'));});d.mc.forEach((it,i)=>{const selected=document.querySelector(`input[name="mc${i}"]:checked`);const ok=!!selected&&Number(selected.value)===it.a;if(ok){detail.mc++;total+=5;}setEvalFeedback('evalFbMc'+i,ok,ok?'Correcto. +5 pts':'Revisar. Respuesta esperada: '+it.o[it.a]);});const expectedLetters=d.pr.terms.map(it=>d.pr.letters[d.pr.shuffledDefs.findIndex(df=>df.def===it.def)]);expectedLetters.forEach((letter,i)=>{const sel=document.querySelector(`[data-pr="${i}"]`);const ok=!!sel&&sel.value===letter;if(sel){sel.classList.toggle('eval-input-ok',ok);sel.classList.toggle('eval-input-no',!ok);}if(ok){detail.pr++;total+=5;}});const prMsg=`Pareados: ${detail.pr}/5 correctos. ${detail.pr===5?'Excelente. +25 pts':'Clave: '+expectedLetters.map((l,i)=>(i+16)+'→'+l).join(' · ')}`;setEvalFeedback('evalFbPr',detail.pr===5,prMsg);const result=document.getElementById('evalAutoResult');if(result){result.className='eval-auto-result '+(total>=70?'eval-auto-pass':'eval-auto-risk');result.innerHTML=`<strong>Resultado automático: ${total}/100 puntos</strong><br><span>Completar: ${detail.cp*5}/25 · V/F: ${detail.tf*5}/25 · Selección: ${detail.mc*5}/25 · Pareados: ${detail.pr*5}/25</span><br><em>Este resultado es solo para revisión en pantalla; la impresión conserva el formato limpio para papel.</em>`;}if(total>=70){pts(8);showToast('🎯 Evaluación calificada: '+total+'/100');}else showToast('🧮 Evaluación calificada: '+total+'/100. Revisa las respuestas marcadas.');}
function printEval(){if(!window._evalPrintData){showToast('⚠️ Genera una evaluación primero');return;}sfx('click');const forma=window._currentEvalForm||1;const d=window._evalPrintData;let s1=`<div class="sec-title"><span>I. Completar el espacio</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div>`;d.cp.forEach((it,i)=>{const q=it.q.replace('___','<span class="cp-blank"></span>');s1+=`<div class="cp-row"><span class="qn">${i+1}.</span><span class="cp-text">${q}</span></div>`;});let s2=`<div class="sec-title"><span>II. Verdadero o Falso</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div>`;d.tf.forEach((it,i)=>{s2+=`<div class="tf-row"><span class="qn">${i+6}.</span><span class="tf-blank"></span><span class="tf-text">${it.q}</span></div>`;});let s3=`<div class="sec-title"><span>III. Selección Múltiple</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div><div class="mc-grid">`;d.mc.forEach((it,i)=>{const opts=it.o.map((op,oi)=>`<label class="mc-opt"><input type="radio" name="mcp${i}"> ${op}</label>`).join('');s3+=`<div class="mc-item"><div class="mc-q"><span class="qn">${i+11}.</span><span>${it.q}</span></div><div class="mc-opts">${opts}</div></div>`;});s3+=`</div>`;let colL='<div class="pr-col"><div class="pr-head">📌 Términos</div>';d.pr.terms.forEach((it,i)=>{colL+=`<div class="pr-item"><span class="pr-num">${i+16}.</span><span class="pr-line"></span>${it.term}</div>`;});colL+='</div>';let colR='<div class="pr-col"><div class="pr-head">🔑 Definiciones</div>';d.pr.shuffledDefs.forEach((it,i)=>{colR+=`<div class="pr-item"><span class="pr-num">${d.pr.letters[i]}.</span>${it.def}</div>`;});colR+='</div>';let s4=`<div class="pr-section"><div class="sec-title"><span>IV. Términos Pareados</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 25%</span></div></div><div class="pr-grid">${colL}${colR}</div></div>`;let pR='';pR+=`<div class="p-sec"><div class="p-ttl">I. Completar</div><table class="p-tbl">`;d.cp.forEach((it,i)=>{pR+=`<tr><td class="pn">${i+1}.</td><td class="pa">${it.a}</td></tr>`;});pR+=`</table></div><div class="p-sec"><div class="p-ttl">II. V o F</div><table class="p-tbl">`;d.tf.forEach((it,i)=>{pR+=`<tr><td class="pn">${i+6}.</td><td class="pa">${it.a?'V':'F'}</td></tr>`;});pR+=`</table></div><div class="p-sec"><div class="p-ttl">III. Selección</div><table class="p-tbl">`;d.mc.forEach((it,i)=>{pR+=`<tr><td class="pn">${i+11}.</td><td class="pa">${it.o[it.a]}</td></tr>`;});pR+=`</table></div><div class="p-sec"><div class="p-ttl">IV. Pareados</div><table class="p-tbl">`;d.pr.terms.forEach((it,i)=>{const l=d.pr.letters[d.pr.shuffledDefs.findIndex(df=>df.def===it.def)];pR+=`<tr><td class="pn">${i+16}.</td><td class="pa">${i+16}→${l}</td></tr>`;});pR+=`</table></div>`;const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Evaluación El deseo y el obstáculo · Ruta del Hilo que Tira · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.12rem 0.4rem;margin:0.22rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #1f6f78;background:#e2f0f1;color:#1f6f78;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#1f6f78;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:58px;border-bottom:1.5px solid #1f6f78;height:12px;}.obt-pct{white-space:nowrap;}.qn{font-weight:700;min-width:22px;flex-shrink:0;}.tf-row{display:flex;align-items:baseline;gap:0.3rem;font-size:10.5pt;line-height:1.3;padding:0.13rem 0.2rem;border-bottom:1px solid #eee;}.tf-blank{display:inline-block;min-width:40px;border-bottom:1.5px solid #111;flex-shrink:0;margin:0 0.18rem;}.tf-text{flex:1;}.mc-item{border:1px solid #ddd;border-radius:4px;padding:0.14rem 0.35rem;margin-bottom:0.1rem;break-inside:avoid;page-break-inside:avoid;}.mc-q{font-size:10.5pt;line-height:1.3;display:flex;gap:0.28rem;margin-bottom:0.07rem;}.mc-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.1rem 0.5rem;}.mc-opts{display:grid;grid-template-columns:repeat(4,1fr);gap:0.04rem 0.15rem;margin-left:0.8rem;}.mc-opt{font-size:9pt;display:flex;align-items:center;gap:0.15rem;}.mc-opt input{width:10px;height:10px;flex-shrink:0;}.cp-row{display:flex;align-items:baseline;gap:0.3rem;font-size:10.5pt;line-height:1.3;padding:0.13rem 0.2rem;border-bottom:1px solid #eee;}.cp-text{flex:1;}.cp-blank{display:inline-block;min-width:150px;border-bottom:1.5px solid #111;margin:0 0.12rem;}.pr-section{margin-top:0.1rem;}.pr-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.08rem 0.4rem;margin-top:0.08rem;}.pr-head{font-size:9pt;font-weight:700;color:#555;margin-bottom:0.1rem;}.pr-item{font-size:10.5pt;padding:0.1rem 0.28rem;background:#e2f0f1;border-radius:3px;margin-bottom:0.07rem;display:flex;align-items:center;gap:0.2rem;line-height:1.2;break-inside:avoid;page-break-inside:avoid;}.pr-num{font-weight:700;color:#1f6f78;min-width:19px;flex-shrink:0;}.pr-line{display:inline-block;min-width:19px;border-bottom:1.5px solid #111;margin-right:0.14rem;flex-shrink:0;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.22rem;padding:0.15rem 0;page-break-before:avoid;break-before:avoid;color:#1f6f78;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #1f6f78;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.25rem 0.4rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.15rem;}.p-tbl{width:100%;border-collapse:collapse;font-size:7.5pt;}.p-tbl tr{border-bottom:1px dotted #ddd;}.p-tbl td{padding:0.07rem 0.12rem;vertical-align:top;}.pn{font-weight:700;width:16px;color:#555;}.pa{color:#007a00;font-weight:600;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Final · El deseo y el obstáculo · Ruta del Hilo que Tira · Etapa 2</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Instituto:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · Cada respuesta vale 5 puntos</p></div>${s1}${s2}${s3}${s4}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100%</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: Evaluación Final · El deseo y el obstáculo · Ruta del Hilo que Tira · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 4 secciones × 5 preguntas × 5 pts c/u</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;const win=window.open('','_blank','');if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);}

