  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">Marca dónde se rompe la cadena de este caso y escribe el hueco en UNA frase. Di si hay brecha o si esto es un acta, qué casilla de la ficha de hilo falta, y con qué arranque de dos frases lo contarías.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos se sostiene como historia, y qué pieza lo sostiene? 2. ¿Qué le falta al otro, y es un defecto o es que pertenece a otro género?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
